//! The comparison of joint/mod.rs for weight k != (2, 2), where our
//! coefficient field is relative: K_g = F[x]/(g) with g irreducible over
//! F = Q(w), a Q-algebra of dimension 2d (basis w^i theta^j), and the
//! eigenvalues need not generate it (in parallel weight they may generate
//! a field not containing F). So the field compared is the one generated by
//! the eigenvalues:
//!
//! * z_t = sum_k (k + 1)^t a_(P_k) for the least t such that every a_P of
//!   ours lies in Q(z) (powers of z, exact linear algebra) and z' generates
//!   the other side's field;
//! * the minimal polynomials of z and z' (both irreducible: fields) must be
//!   equal, so z -> z' is an isomorphism Q(z) -> Q(z');
//! * every a_P = c_P(z) and a'_P = c_P(z') with the same c_P.

#![allow(dead_code)]

use crate::joint::{solve, Field, Q};
use sagebrush_bigint::BigInt;
use sagebrush_hmf::fpoly::{FInt, FPoly};

/// A finite-dimensional commutative Q-algebra given by its multiplication.
pub struct Alg {
    pub n: usize,
    one: Vec<Q>,
    mul: Box<dyn Fn(&[Q], &[Q]) -> Vec<Q>>,
}

fn q(x: &BigInt) -> Q {
    Q::new(x.clone(), BigInt::from(1i64))
}

/// (a0 + a1 w)(b0 + b1 w), w^2 = w + 1.
fn fmul(a: (&Q, &Q), b: (&Q, &Q)) -> (Q, Q) {
    let bd = a.1.mul(b.1);
    (a.0.mul(b.0).add(&bd), a.0.mul(b.1).add(&a.1.mul(b.0)).add(&bd))
}

impl Alg {
    /// An absolute field Q[t]/(f).
    pub fn absolute(k: Field) -> Alg {
        let n = k.degree();
        let one = k.one();
        Alg { n, one, mul: Box::new(move |a, b| k.mul(a, b)) }
    }
    /// K_g = F[x]/(g), g monic in O_F[x]; coordinates (index 2j + i) of
    /// w^i x^j.
    pub fn relative(g: &FPoly) -> Alg {
        let d = g.len() - 1;
        let gq: Vec<(Q, Q)> = g.iter().map(|c| (q(&c.a), q(&c.b))).collect();
        let mut one = vec![Q::zero(); 2 * d];
        one[0] = Q::int(1);
        let mul = move |a: &[Q], b: &[Q]| -> Vec<Q> {
            let mut w: Vec<(Q, Q)> = vec![(Q::zero(), Q::zero()); 2 * d];
            for i in 0..d {
                let x = (&a[2 * i], &a[2 * i + 1]);
                if x.0.is_zero() && x.1.is_zero() {
                    continue;
                }
                for j in 0..d {
                    let y = (&b[2 * j], &b[2 * j + 1]);
                    let (s, t) = fmul(x, y);
                    w[i + j] = (w[i + j].0.add(&s), w[i + j].1.add(&t));
                }
            }
            for k in (d..2 * d).rev() {
                let c = w[k].clone();
                if c.0.is_zero() && c.1.is_zero() {
                    continue;
                }
                for i in 0..=d {
                    let (s, t) = fmul((&c.0, &c.1), (&gq[i].0, &gq[i].1));
                    w[k - d + i] = (w[k - d + i].0.sub(&s), w[k - d + i].1.sub(&t));
                }
            }
            (0..2 * d).map(|k| if k % 2 == 0 { w[k / 2].0.clone() } else { w[k / 2].1.clone() }).collect()
        };
        Alg { n: 2 * d, one, mul: Box::new(mul) }
    }
    pub fn mul(&self, a: &[Q], b: &[Q]) -> Vec<Q> {
        (self.mul)(a, b)
    }
}

/// Our eigenvalue a = h(theta)/g'(theta) in K_g, from h in O_F[x].
pub fn relative_eigenvalue(alg: &Alg, g: &FPoly, h: &FPoly) -> Vec<Q> {
    let n = alg.n;
    let embed = |f: &[FInt]| -> Vec<Q> {
        let mut v = vec![Q::zero(); n];
        for (j, c) in f.iter().enumerate() {
            v[2 * j] = q(&c.a);
            v[2 * j + 1] = q(&c.b);
        }
        v
    };
    let dg: Vec<FInt> = g.iter().enumerate().skip(1).map(|(j, c)| FInt::new(&c.a * &BigInt::from(j as i64), &c.b * &BigInt::from(j as i64))).collect();
    let gp = embed(&dg);
    // solve g' a = h: columns g' e_k
    let cols: Vec<Vec<Q>> = (0..n)
        .map(|k| {
            let mut e = vec![Q::zero(); n];
            e[k] = Q::int(1);
            alg.mul(&gp, &e)
        })
        .collect();
    solve(&cols, &embed(h)).expect("g'(theta) is invertible in a field")
}

/// The minimal polynomial of z (monic, constant term first) and the
/// coordinates of each a in 1, z, ..., z^(e-1), or None if some a is not in
/// Q(z).
fn minpoly_coordinates(alg: &Alg, z: &[Q], aps: &[Vec<Q>]) -> Option<(Vec<Q>, Vec<Vec<Q>>)> {
    let mut pows = vec![alg.one.clone()];
    let m = loop {
        let next = alg.mul(pows.last().unwrap(), z);
        match solve(&pows, &next) {
            Some(c) => {
                let mut m: Vec<Q> = c.iter().map(|x| Q::zero().sub(x)).collect();
                m.push(Q::int(1));
                break m;
            }
            None => pows.push(next),
        }
    };
    let coords: Option<Vec<Vec<Q>>> = aps.iter().map(|a| solve(&pows, a)).collect();
    Some((m, coords?))
}

fn combination(n: usize, aps: &[Vec<Q>], t: u32) -> Vec<Q> {
    let mut z = vec![Q::zero(); n];
    for (i, a) in aps.iter().enumerate() {
        let c = Q::new(BigInt::from(i as i64 + 1).pow(t), BigInt::from(1i64));
        for (x, y) in z.iter_mut().zip(a) {
            *x = x.add(&y.mul(&c));
        }
    }
    z
}

/// Whether our eigenvalues (in alg, a field) and theirs (in their field,
/// generated by them) agree under one isomorphism of the fields they
/// generate; Ok(t) gives the t used.
pub fn joint_alg(ours: &Alg, aps: &[Vec<Q>], theirs: &Alg, aps2: &[Vec<Q>]) -> Result<u32, String> {
    if aps.len() != aps2.len() {
        return Err("different numbers of primes".into());
    }
    for t in 1..=12u32 {
        let z = combination(ours.n, aps, t);
        let Some((m, c)) = minpoly_coordinates(ours, &z, aps) else {
            continue;
        };
        let z2 = combination(theirs.n, aps2, t);
        let Some((m2, c2)) = minpoly_coordinates(theirs, &z2, aps2) else {
            continue;
        };
        if m2.len() - 1 != theirs.n {
            continue; // z' does not generate their field
        }
        if m != m2 {
            return Err(format!("z_{} has different minimal polynomials", t));
        }
        return match c.iter().zip(&c2).position(|(x, y)| x != y) {
            None => Ok(t),
            Some(i) => Err(format!("a_P at the prime with index {} differs under z_{} -> z_{}'", i, t, t)),
        };
    }
    Err("no z_t (t <= 12) generates the fields of the eigenvalues".into())
}
